insert into dnew values
(1, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'On haemodynamic monitoring, a patient shows low cardiac output, high systemic vascular resistance, and a high pulmonary capillary wedge pressure. This pattern is most consistent with:', '["Hypovolaemic shock", "Cardiogenic shock", "Distributive (septic) shock", "Normal haemodynamics"]'::jsonb, 1, 'Cardiogenic shock classically shows low cardiac output with compensatory high SVR and elevated filling pressures (high wedge pressure) due to pump failure.', 'Cardiovascular'),
(2, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'A patient on continuous ECG monitoring develops wide, bizarre QRS complexes at a rate of 160/min with no discernible P waves, and is hypotensive. This rhythm most likely represents:', '["Ventricular tachycardia", "Sinus tachycardia", "First-degree heart block", "Normal sinus rhythm"]'::jsonb, 0, 'Wide, bizarre QRS complexes without P waves at a rapid rate is characteristic of ventricular tachycardia, a life-threatening arrhythmia especially when the patient is unstable.', 'Cardiovascular'),
(3, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'Haemodynamic monitoring in cardiogenic shock classically shows:', '["Low systemic vascular resistance", "Normal filling pressures with high cardiac output", "Low pulmonary capillary wedge pressure and high cardiac output", "High pulmonary capillary wedge pressure and low cardiac output"]'::jsonb, 3, 'Cardiogenic shock reflects pump failure, producing elevated filling pressures (high PCWP) as blood backs up while cardiac output falls due to poor contractility.', 'Cardiovascular'),
(4, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'Torsades de pointes, a polymorphic ventricular tachycardia, is classically associated with:', '["A shortened QT interval", "Normal QT interval in all cases", "Complete heart block only", "A prolonged QT interval"]'::jsonb, 3, 'Torsades de pointes arises in the setting of a prolonged QT interval (congenital or drug-induced), and IV magnesium sulfate is a key treatment regardless of magnesium level.', 'Cardiovascular'),
(5, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'A patient in cardiogenic shock has a low cardiac output despite adequate preload. Which mechanism is most likely responsible?', '["Bradycardia-induced increase in stroke volume", "Impaired myocardial contractility", "Excessively low afterload", "Excess venous return"]'::jsonb, 1, 'Cardiogenic shock results from primary pump (contractility) failure, so cardiac output remains low even with adequate filling.', 'Cardiovascular'),
(6, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'A patient with an inferior STEMI becomes hypotensive after sublingual GTN, with clear lungs and a raised JVP. The likely cause is:', '["Cardiac tamponade from free wall rupture of the LV", "Allergic reaction to the GTN tablet given", "Left ventricular failure with pulmonary oedema", "Right ventricular infarction"]'::jsonb, 3, 'RV infarction is preload-dependent; nitrates and diuretics cause hypotension. Treat with IV fluids and avoid nitrates.', 'Cardiovascular'),
(7, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'The door-to-balloon target for primary PCI in STEMI is within:', '["30 minutes of discharge", "6 hours of arrival", "24 hours of the onset", "90 minutes"]'::jsonb, 3, 'If PCI cannot be done within 120 minutes, thrombolysis within 30 minutes of arrival is preferred.', 'Cardiovascular'),
(8, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'A contraindication to thrombolysis in STEMI is:', '["Controlled hypertension on treatment", "Ischaemic stroke within 3 months", "Age over 60 years with diabetes", "Previous MI more than 5 years ago"]'::jsonb, 1, 'Other absolute contraindications include previous haemorrhagic stroke, active bleeding and aortic dissection.', 'Cardiovascular'),
(9, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'Successful reperfusion after thrombolysis is suggested by:', '["Complete heart block develops with a slow ventricular rate", "ST elevation falls by over 50% and the pain settles", "Chest pain persists with steadily rising ST segments", "New Q waves appear in the same leads within an hour"]'::jsonb, 1, 'Reperfusion arrhythmias (e.g. accelerated idioventricular rhythm) may also occur.', 'Cardiovascular'),
(10, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'A patient 4 days after MI develops a new harsh pansystolic murmur and acute pulmonary oedema. The nurse suspects:', '["Acute pericarditis with a pericardial friction rub", "Normal healing of the infarct with scar formation", "Dressler''s syndrome with fever and pleuritic pain", "Papillary muscle or ventricular septal rupture"]'::jsonb, 3, 'These mechanical complications occur 3–5 days after MI and need urgent surgery.', 'Cardiovascular'),
(11, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'Hypertensive emergency differs from hypertensive urgency because emergency has:', '["A history of hypertension", "Symptoms of headache only", "A systolic BP above 180", "Acute end-organ damage"]'::jsonb, 3, 'Examples of end-organ damage: encephalopathy, pulmonary oedema, ACS, AKI, eclampsia and aortic dissection.', 'Cardiovascular'),
(12, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'In hypertensive emergency (without aortic dissection), the MAP should be reduced in the first hour by no more than:', '["5%", "75%", "50%", "25%"]'::jsonb, 3, 'Rapid falls cause cerebral, coronary and renal ischaemia. Titratable IV agents (labetalol, GTN, nicardipine) are used.', 'Cardiovascular'),
(13, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'A patient with tearing chest pain radiating to the back and unequal arm blood pressures most likely has:', '["Oesophageal spasm", "Pulmonary embolism", "Aortic dissection", "Acute pericarditis"]'::jsonb, 2, 'Thrombolysis is contraindicated. Heart rate and BP are lowered rapidly with IV beta-blockers.', 'Cardiovascular'),
(14, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'In aortic dissection, IV beta-blockers are given before vasodilators to:', '["Raise the blood pressure before surgical repair", "Prevent reflex tachycardia that raises shear stress", "Increase the cardiac output and organ perfusion", "Dissolve the intimal flap and close the false lumen"]'::jsonb, 1, 'Target HR about 60 and systolic BP 100–120 mmHg.', 'Cardiovascular'),
(15, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'A patient with new atrial fibrillation (rate 160) becomes hypotensive and confused. The immediate treatment is:', '["Synchronised DC cardioversion", "Observation with repeat ECG in 24 hours", "IV furosemide bolus and fluid restriction", "Oral digoxin loading over 24 hours"]'::jsonb, 0, 'Unstable tachyarrhythmias with adverse features need synchronised shock.', 'Cardiovascular'),
(16, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'Before elective cardioversion of AF lasting more than 48 hours, the patient needs:', '["Only a chest X-ray to check the heart size", "A single loading dose of aspirin on the day", "No preparation, as long as the patient is stable", "3 weeks of anticoagulation, or TOE to exclude thrombus"]'::jsonb, 3, 'Left atrial thrombus can embolise after cardioversion, causing stroke.', 'Cardiovascular'),
(17, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'Adenosine is used in narrow-complex regular tachycardia (SVT). The nurse should warn the patient about:', '["Permanent bradycardia needing a pacemaker", "Long-lasting drowsiness for several hours after", "Severe hypertension lasting for several hours", "Brief chest tightness and a sense of impending doom"]'::jsonb, 3, 'Adenosine has a half-life of seconds; give as a rapid bolus with a saline flush into a large vein.', 'Cardiovascular'),
(18, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'Torsades de pointes is treated first with:', '["IV amiodarone 300 mg", "IV digoxin 500 micrograms", "IV adenosine 6 mg", "IV magnesium sulphate 2 g"]'::jsonb, 3, 'Stop QT-prolonging drugs and correct potassium; pacing may be needed.', 'Cardiovascular'),
(19, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'Cardiogenic shock after a large anterior MI is treated with:', '["Routine high-dose diuretics only, until the BP improves", "IV beta-blockers to lower the heart rate and oxygen use", "Urgent revascularisation, inotropes and IABP support", "Large fluid boluses alone to fill the failing ventricle"]'::jsonb, 2, 'Mortality is high; early PCI improves survival.', 'Cardiovascular'),
(20, 'Medical-Surgical Emergencies I: Cardiovascular Emergencies', 'Troponin in acute MI begins to rise within about:', '["30 minutes of symptom onset", "7 days after the event", "3–4 hours of symptom onset", "24 hours only"]'::jsonb, 2, 'It peaks at 24–48 hours and remains raised for up to 2 weeks.', 'Cardiovascular'),
(21, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'A patient in DKA presents with deep, rapid breathing (Kussmaul respirations) and a fruity breath odour. This reflects the body''s attempt to:', '["Increase oxygen delivery with no relation to acid-base status", "Reduce blood glucose directly through breathing", "Compensate for respiratory alkalosis", "Compensate for metabolic acidosis by blowing off CO2"]'::jsonb, 3, 'Kussmaul respirations are a compensatory response to the metabolic acidosis of DKA, with deep rapid breathing reducing CO2 to help raise pH; the fruity odour comes from exhaled ketones.', 'GI, Endocrine & Metabolic'),
(22, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'A patient with diabetic ketoacidosis has K⁺ 5.2 mEq/L before insulin therapy. After starting insulin, which K⁺ level indicates effective treatment?', '["4.8 mEq/L", "3.9 mEq/L", "5.0 mEq/L", "3.2 mEq/L"]'::jsonb, 3, 'Insulin drives K⁺ into cells, causing hypokalemia. A drop to 3.2 mEq/L reflects successful intracellular shift but requires replacement to prevent arrhythmias.', 'GI, Endocrine & Metabolic'),
(23, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'The LEAST important part of initial DKA treatment is:', '["Lowering blood glucose with insulin", "Giving sodium bicarbonate", "Giving potassium chloride", "Giving fluids"]'::jsonb, 1, 'Bicarbonate is rarely needed in DKA (only if pH <6.9). Fluids, insulin and potassium come first.', 'GI, Endocrine & Metabolic'),
(24, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'In DKA, insulin infusion is started at a fixed rate of:', '["10 units/hour for all", "0.1 units/kg/hour", "1 unit/kg/hour", "0.01 units/kg/hour"]'::jsonb, 1, 'Ketones should fall by about 0.5 mmol/L/hour; add 10% dextrose when glucose falls below 14 mmol/L.', 'GI, Endocrine & Metabolic'),
(25, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'Insulin should not be started in DKA until the potassium is at least:', '["2.0 mmol/L", "6.5 mmol/L", "3.3 mmol/L", "5.5 mmol/L"]'::jsonb, 2, 'Insulin drives potassium into cells; starting it with hypokalaemia can cause fatal arrhythmias.', 'GI, Endocrine & Metabolic'),
(26, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'A major risk of correcting DKA too rapidly in a child is:', '["Hyperkalaemia", "Hypernatraemia", "Cerebral oedema", "Pulmonary embolism"]'::jsonb, 2, 'Warning signs are headache, falling GCS, bradycardia and hypertension.', 'GI, Endocrine & Metabolic'),
(27, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'Hyperosmolar hyperglycaemic state differs from DKA because HHS has:', '["Low serum osmolality with a metabolic alkalosis", "Hypoglycaemia with confusion and sweating", "Very high glucose and osmolality with little ketosis", "Severe ketoacidosis with a low or normal glucose"]'::jsonb, 2, 'HHS occurs in older type 2 diabetics; fluid deficit is huge and thrombosis risk is high.', 'GI, Endocrine & Metabolic'),
(28, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'In HHS, the first-line treatment is:', '["Hypotonic fluid rapidly", "Sodium bicarbonate infusion", "High-dose insulin bolus", "Slow IV 0.9% saline rehydration"]'::jsonb, 3, 'Rapid falls in osmolality risk cerebral oedema; insulin is started at a low rate if glucose stops falling.', 'GI, Endocrine & Metabolic'),
(29, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'Thyroid storm presents with:', '["Hyperpyrexia, tachyarrhythmia, agitation, heart failure", "Hypothermia, bradycardia and a slow decline into coma", "Hypoglycaemia with low sodium and high potassium", "Weight gain, cold intolerance and slowed thinking"]'::jsonb, 0, 'Treatment: beta-blocker, antithyroid drug (PTU/carbimazole), iodine an hour later, steroids and cooling.', 'GI, Endocrine & Metabolic'),
(30, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'Myxoedema coma is characterised by:', '["Hypothermia, bradycardia, hypoventilation, coma", "Hyperthermia, tachycardia and agitation", "Severe hypertension with a headache", "Diarrhoea, weight loss and tremor"]'::jsonb, 0, 'Give IV thyroxine (or T3) with hydrocortisone, passive warming and ventilatory support.', 'GI, Endocrine & Metabolic'),
(31, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'Addisonian (adrenal) crisis typically presents with:', '["Hypertension with low potassium and alkalosis", "Hypotension, low Na⁺, high K⁺ and low glucose", "High glucose with weight gain and striae", "High sodium with polyuria and thirst"]'::jsonb, 1, 'Treat with IV hydrocortisone 100 mg, fluids and glucose.', 'GI, Endocrine & Metabolic'),
(32, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'The first drug for anaphylaxis with stridor and hypotension is:', '["Nebulised salbutamol 5 mg via mask", "IV hydrocortisone 200 mg bolus", "IM adrenaline 0.5 mg (1:1000)", "IV chlorphenamine 10 mg slowly"]'::jsonb, 2, 'Antihistamines and steroids are second-line. Repeat adrenaline after 5 minutes if needed.', 'GI, Endocrine & Metabolic'),
(33, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'After anaphylaxis is treated, the patient is observed for at least 6–12 hours because of:', '["Steroid side effects", "Biphasic (late) reactions", "Delayed drug absorption", "Hypoglycaemia"]'::jsonb, 1, 'Serum tryptase is taken to confirm anaphylaxis.', 'GI, Endocrine & Metabolic'),
(34, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'Severe hypoglycaemia in an unconscious ICU patient is treated with:', '["IV insulin 10 units to reset the glucose control", "Oral glucose gel placed into the patient''s mouth", "IM glucagon only, repeated every 10 minutes", "IV 10% dextrose 150–200 mL (or 20% dextrose 75–100 mL)"]'::jsonb, 3, 'Recheck glucose in 10–15 minutes; find the cause.', 'GI, Endocrine & Metabolic'),
(35, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'Hyperkalaemia with ECG changes is first treated with:', '["Oral potassium binders as the only treatment", "IV calcium gluconate 10% to protect the heart", "IV furosemide alone to excrete potassium", "IV potassium chloride to correct the ECG"]'::jsonb, 1, 'Then insulin with dextrose and salbutamol shift potassium into cells.', 'GI, Endocrine & Metabolic'),
(36, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'Syndrome of inappropriate ADH (SIADH) causes:', '["High sodium with very dilute urine and thirst", "Low sodium with concentrated urine, euvolaemic", "High potassium with a metabolic acidosis", "Hypovolaemia with polyuria and low urine sodium"]'::jsonb, 1, 'Treat with fluid restriction; correct sodium slowly (no more than 8–10 mmol/L in 24 hours).', 'GI, Endocrine & Metabolic'),
(37, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'Too-rapid correction of chronic hyponatraemia can cause:', '["Severe hyperkalaemia and arrhythmia", "Osmotic demyelination syndrome", "Acute intracerebral haemorrhage", "Pulmonary oedema and hypoxia"]'::jsonb, 1, 'It causes quadriparesis, dysarthria and ''locked-in'' syndrome.', 'GI, Endocrine & Metabolic'),
(38, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'Lactic acidosis in septic shock mainly reflects:', '["Tissue hypoperfusion and anaerobic metabolism", "Renal retention of bicarbonate in shock", "Liver overproduction of glucose from stress", "Excess dietary lactate from enteral feeding"]'::jsonb, 0, 'Lactate above 4 mmol/L signals severe shock; serial lactate guides resuscitation.', 'GI, Endocrine & Metabolic'),
(39, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'Paracetamol overdose is treated with:', '["IV flumazenil", "IV N-acetylcysteine according to the nomogram", "Oral activated charcoal only after 24 hours", "IV naloxone"]'::jsonb, 1, 'The 4-hour level guides treatment; staggered overdoses are treated regardless.', 'GI, Endocrine & Metabolic'),
(40, 'Medical-Surgical Emergencies I: Metabolic, Endocrine and Allergic Emergencies', 'Organophosphate poisoning is treated with:', '["Naloxone and flumazenil given together", "Neostigmine infusion to reverse weakness", "Adrenaline and hydrocortisone IV", "Atropine until the chest is dry, plus pralidoxime"]'::jsonb, 3, 'Atropine is titrated to drying of secretions, HR above 80 and SBP above 80 mmHg.', 'GI, Endocrine & Metabolic'),
(41, 'Information and Communication Technology in Critical Care', 'Identify the five main components of a computer system in their order?', '["Modem, Keyboard, Word Processor, Printer, Screen", "Memory, Video card, Monitor, Software, Hardware", "CPU, CD-ROM, Mouse, Keyboard, Sound card", "CPU, Memory, System bus, Input, Output"]'::jsonb, 3, 'CPU, memory, system bus, input, and output are the five core computer system components.', 'Nursing Informatics & ICT'),
(42, 'Information and Communication Technology in Critical Care', 'Multi-user processing in a hospital computer system allows:', '["Only one staff member to use the system at any given time", "Multiple users to access and use the system concurrently", "No simultaneous data entry by different departments", "Only administrators to log in"]'::jsonb, 1, 'Multi-user systems are designed so several staff members across departments can access and use the system at the same time.', 'Nursing Informatics & ICT'),
(43, 'Information and Communication Technology in Critical Care', 'A nurse is explaining the units of data to a patient. The smallest unit of data in a computer is a:', '["Bit", "Kilobyte", "Megabyte", "Byte"]'::jsonb, 0, 'A bit (binary digit) is the most basic unit of information in computing and is a one or a zero. A byte is a group of 8 bits. The other options are larger units of data.', 'Nursing Informatics & ICT'),
(44, 'Information and Communication Technology in Critical Care', 'A hybrid computer used in ICU monitoring combines:', '["Analogue signal input with digital processing", "A mainframe linked to a microcomputer", "Two digital computers working together", "Hardware and software in one box only"]'::jsonb, 0, 'Monitors convert continuous analogue signals (ECG, pressure) into digital values.', 'Nursing Informatics & ICT'),
(45, 'Information and Communication Technology in Critical Care', 'Computers classified by size, from largest to smallest, are:', '["Server, router, modem, scanner", "Microcomputer, minicomputer, mainframe, supercomputer", "Supercomputer, mainframe, minicomputer, microcomputer", "Laptop, desktop, tablet, mainframe"]'::jsonb, 2, 'Most hospital desktops and laptops are microcomputers.', 'Nursing Informatics & ICT'),
(46, 'Information and Communication Technology in Critical Care', 'The first generation of computers used:', '["Integrated circuits", "Transistors", "Microprocessors", "Vacuum tubes"]'::jsonb, 3, 'Second: transistors; third: integrated circuits; fourth: microprocessors; fifth: artificial intelligence.', 'Nursing Informatics & ICT'),
(47, 'Information and Communication Technology in Critical Care', 'The control unit of the CPU:', '["Performs arithmetic and nothing else", "Directs and coordinates the computer''s operations", "Prints the results of each calculation", "Stores data permanently when switched off"]'::jsonb, 1, 'The ALU performs calculations and logic; memory stores data and programs.', 'Nursing Informatics & ICT'),
(48, 'Information and Communication Technology in Critical Care', 'A barcode scanner used for patient identification is an example of:', '["A processing device", "An input device", "An output device", "A storage device"]'::jsonb, 1, 'Output devices include printers, monitors and speakers.', 'Nursing Informatics & ICT'),
(49, 'Information and Communication Technology in Critical Care', 'Utility software includes:', '["Microsoft Word, Excel and PowerPoint", "Antivirus, compression and backup programs", "The ICU patient monitoring display screen", "The computer''s processor chip and memory"]'::jsonb, 1, 'System software runs the computer; application software performs user tasks.', 'Nursing Informatics & ICT'),
(50, 'Information and Communication Technology in Critical Care', 'A computer network within one hospital building is a:', '["Local Area Network (LAN)", "Metropolitan Area Network", "Wide Area Network (WAN)", "Personal Area Network"]'::jsonb, 0, 'A WAN links hospitals across cities; the internet is the largest WAN.', 'Nursing Informatics & ICT'),
(51, 'Information and Communication Technology in Critical Care', 'Electronic mail (e-mail) of patient information should be:', '["Printed and posted on the ward notice board", "Encrypted and sent only to authorised people", "Shared in staff group chats for quick advice", "Sent to personal accounts because it is faster"]'::jsonb, 1, 'Confidentiality laws apply to electronic communication.', 'Nursing Informatics & ICT'),
(52, 'Information and Communication Technology in Critical Care', 'Telemedicine in critical care (tele-ICU) allows:', '["Surgery to be performed by computers on their own", "Drugs to be sent to the patient by electronic mail", "Remote specialists to monitor and advise on ICU patients", "Patients to be cared for without any bedside nurses"]'::jsonb, 2, 'It improves access to intensivists in remote hospitals.', 'Nursing Informatics & ICT'),
(53, 'Information and Communication Technology in Critical Care', 'A CT scanner and ultrasound machine are examples of ICT in:', '["Treatment only", "Administration only", "Diagnosis", "Nursing education only"]'::jsonb, 2, 'Monitoring devices (oximeter, cardiac monitor) and treatment devices (infusion pumps, radiotherapy) are other categories.', 'Nursing Informatics & ICT'),
(54, 'Information and Communication Technology in Critical Care', 'An infusion pump with a drug library (''smart pump'') improves safety by:', '["Alerting the nurse to doses outside safe limits", "Removing the need to check the prescription", "Calculating the diagnosis from the drug list", "Choosing the correct drug for the patient"]'::jsonb, 0, 'Hard and soft limits reduce programming errors.', 'Nursing Informatics & ICT'),
(55, 'Information and Communication Technology in Critical Care', 'A computer-based patient record differs from a paper record because it:', '["It has no confidentiality rules attached to it", "It can be used by authorised staff in many places at once", "It never needs any backup or protection from loss", "It cannot be audited or checked after it is written"]'::jsonb, 1, 'It improves legibility, retrieval and data analysis.', 'Nursing Informatics & ICT'),
(56, 'Information and Communication Technology in Critical Care', 'Data standardisation in nursing informatics is important because it:', '["It prevents any coding of nursing diagnoses", "It reduces the need for any documentation", "It lets data be compared, shared and analysed", "It increases the use of free-text descriptions"]'::jsonb, 2, 'NANDA, NIC and NOC are examples of standardised nursing terminologies.', 'Nursing Informatics & ICT'),
(57, 'Information and Communication Technology in Critical Care', 'A ''virus'' in computing is:', '["An input device such as a scanner", "A malicious program that damages files", "A cracked or broken computer screen", "A type of portable storage disk"]'::jsonb, 1, 'Antivirus software, updates and safe browsing protect hospital systems.', 'Nursing Informatics & ICT'),
(58, 'Information and Communication Technology in Critical Care', 'A gigabyte (GB) is approximately:', '["1 terabyte", "1000 megabytes", "100 kilobytes", "10 bytes"]'::jsonb, 1, '1 byte = 8 bits; 1 KB ≈ 1000 bytes; 1 MB ≈ 1000 KB.', 'Nursing Informatics & ICT'),
(59, 'Information and Communication Technology in Critical Care', 'The main effect of ICT on quality nursing care in ICU is:', '["Increasing the paperwork for every patient", "Reducing the need for consent from patients", "Faster access to accurate information, fewer errors", "Removing the need for nurses at the bedside"]'::jsonb, 2, 'Examples include electronic charting, alerts and decision support.', 'Nursing Informatics & ICT'),
(60, 'Information and Communication Technology in Critical Care', 'Real-time (online) processing is used in ICU for:', '["Annual ICU budget planning", "Continuous monitoring of vital signs", "Yearly staff appraisal reports", "Monthly salary calculations"]'::jsonb, 1, 'Batch processing handles grouped data later, e.g. payroll.', 'Nursing Informatics & ICT'),
(61, 'Family Survival, Stress and the Unconscious Patient', 'A family caregiver of a chronically critically ill ICU patient reports exhaustion, feeling overwhelmed by care responsibilities, and increasing strain in the relationship with the patient. The most appropriate NANDA-I diagnosis is:', '["Ineffective Family Coping", "Interrupted Family Processes", "Compromised Family Coping", "Caregiver Role Strain"]'::jsonb, 3, 'Caregiver Role Strain specifically describes difficulty in performing the family caregiver role, evidenced by exhaustion, feeling overwhelmed, and relational strain.', 'Ethics, Law & Management'),
(62, 'Family Survival, Stress and the Unconscious Patient', 'Which NANDA-I diagnosis is most appropriate for a patient who is unconscious with an absent gag reflex and is receiving enteral tube feedings, placing them at risk of food or fluid entering the airway?', '["Risk for Suffocation", "Impaired Swallowing", "Risk for Aspiration", "Ineffective Airway Clearance"]'::jsonb, 2, 'Risk for Aspiration describes vulnerability for gastrointestinal secretions, oropharyngeal secretions, or solids/fluids entering the tracheobronchial passages, which fits an unconscious patient with an absent gag reflex receiving tube feeds.', 'Ethics, Law & Management'),
(63, 'Family Survival, Stress and the Unconscious Patient', 'In assessment of unconscious patient which of this is the ideal sequence used?', '["EACAB", "ABCDE", "CABDE", "BACDE"]'::jsonb, 1, 'ABCDE is the standard structured assessment sequence for an unconscious patient.', 'Ethics, Law & Management'),
(64, 'Family Survival, Stress and the Unconscious Patient', 'Selye''s General Adaptation Syndrome has three stages in order:', '["Exhaustion, alarm, resistance", "Alarm, resistance, exhaustion", "Shock, denial, acceptance", "Resistance, alarm, exhaustion"]'::jsonb, 1, 'Prolonged stress exhausts adaptive resources, leading to illness.', 'Ethics, Law & Management'),
(65, 'Family Survival, Stress and the Unconscious Patient', 'During the alarm stage of GAS, the body shows:', '["Reduced cortisol and adrenaline secretion", "Bradycardia, hypotension and low blood glucose", "Deep sleep, relaxation and slow breathing", "Sympathetic activation: high HR, BP and glucose"]'::jsonb, 3, 'The ''fight or flight'' response is mediated by catecholamines and cortisol.', 'Ethics, Law & Management'),
(66, 'Family Survival, Stress and the Unconscious Patient', 'The most important need reported by families of ICU patients is:', '["Unlimited visiting at night for all relatives", "Free meals in the hospital canteen each day", "Honest, understandable information about the patient", "A private waiting room with a television only"]'::jsonb, 2, 'Leske''s Critical Care Family Needs Inventory ranks assurance and information highest.', 'Ethics, Law & Management'),
(67, 'Family Survival, Stress and the Unconscious Patient', 'A wife shouts at the ICU nurse that her husband is ''not being cared for''. This is most likely:', '["A clear sign that she intends to sue the hospital", "Normal behaviour that needs no response from staff", "Evidence of a mental illness needing a psychiatrist", "An expression of fear and helplessness under stress"]'::jsonb, 3, 'Acknowledge her feelings, listen and provide information calmly.', 'Ethics, Law & Management'),
(68, 'Family Survival, Stress and the Unconscious Patient', 'Signs that a family is not coping include:', '["Expressing sadness and crying at the bedside", "Asking appropriate questions about the care", "Visiting regularly at the permitted times", "Withdrawal, constant anger, no decision-making"]'::jsonb, 3, 'Refer to social work, counselling or spiritual support.', 'Ethics, Law & Management'),
(69, 'Family Survival, Stress and the Unconscious Patient', 'A nursing diagnosis for a family in crisis in ICU could be:', '["Interrupted family processes related to critical illness", "Risk for infection related to invasive lines", "Acute pain related to the surgical incision", "Ineffective airway clearance related to secretions"]'::jsonb, 0, 'Interventions include information, involvement in care and support services.', 'Ethics, Law & Management'),
(70, 'Family Survival, Stress and the Unconscious Patient', 'Family presence during resuscitation, when supported by a staff member, has been shown to:', '["It always disrupts the resuscitation team''s work", "It increases legal claims in every case", "Helps relatives cope, without disrupting care", "It lengthens the resuscitation time considerably"]'::jsonb, 2, 'A designated staff member should stay with the family.', 'Ethics, Law & Management'),
(71, 'Family Survival, Stress and the Unconscious Patient', 'Glasgow Coma Scale of E1 V1 M4 means the patient:', '["Obeys commands but makes no sound at all", "Is fully conscious and orientated to place", "Opens eyes to speech and is confused in speech", "No eye opening, no voice, and withdraws from pain"]'::jsonb, 3, 'Total = 6. M4 is withdrawal; M3 is abnormal flexion.', 'Ethics, Law & Management'),
(72, 'Family Survival, Stress and the Unconscious Patient', 'The priority nursing care of an unconscious patient is to:', '["Restrict all IV and enteral fluids", "Keep the airway patent and prevent aspiration", "Begin oral feeding to maintain nutrition", "Remove all monitoring to allow rest"]'::jsonb, 1, 'Lateral or head-up positioning and suction protect the airway.', 'Ethics, Law & Management'),
(73, 'Family Survival, Stress and the Unconscious Patient', 'Eye care in the unconscious patient prevents:', '["Acute angle-closure glaucoma", "Retinal detachment and blindness", "Corneal ulceration from exposure", "Cataract formation in the lens"]'::jsonb, 2, 'Lubricants, moist gauze or taping the eyelids closed are used.', 'Ethics, Law & Management'),
(74, 'Family Survival, Stress and the Unconscious Patient', 'Mouth care in the unconscious ventilated patient is done with chlorhexidine to:', '["Whiten the teeth for the family", "Reduce oral ulcers and nothing else", "Stimulate the flow of saliva", "Reduce ventilator-associated pneumonia"]'::jsonb, 3, 'Oral care is part of the VAP bundle.', 'Ethics, Law & Management'),
(75, 'Family Survival, Stress and the Unconscious Patient', 'Passive range-of-motion exercises in the unconscious patient prevent:', '["Hypoglycaemia", "Urinary infection", "Contractures and muscle wasting", "Pressure ulcers on the heels"]'::jsonb, 2, 'Splints maintain joint position.', 'Ethics, Law & Management'),
(76, 'Family Survival, Stress and the Unconscious Patient', 'Hearing is thought to be the last sense lost in unconscious patients, so nurses should:', '["Play loud music continuously", "Talk to the patient and explain procedures", "Discuss the prognosis loudly at the bedside", "Avoid speaking near the bed"]'::jsonb, 1, 'This respects dignity and may reduce distress.', 'Ethics, Law & Management'),
(77, 'Family Survival, Stress and the Unconscious Patient', 'A family member caring for a long-term ICU patient feels exhausted and overwhelmed. This is called:', '["Caregiver burden (role strain)", "Compassion satisfaction", "Normal anticipatory grieving", "Learned resilience"]'::jsonb, 0, 'Respite and support services help.', 'Ethics, Law & Management'),
(78, 'Family Survival, Stress and the Unconscious Patient', 'Coping mechanisms that families use in crisis include:', '["Seeking information, spiritual and social support", "Avoiding visiting the patient completely", "Ignoring all the medical and nursing staff", "Refusing all information about the patient"]'::jsonb, 0, 'Nurses reinforce positive coping.', 'Ethics, Law & Management'),
(79, 'Family Survival, Stress and the Unconscious Patient', 'Post-intensive care syndrome-family (PICS-F) includes:', '["Financial benefit to the family after discharge", "Anxiety, depression and PTSD in relatives", "Improved family relationships in every case", "Infection transmitted to the family members"]'::jsonb, 1, 'Follow-up clinics and diaries may reduce it.', 'Ethics, Law & Management'),
(80, 'Family Survival, Stress and the Unconscious Patient', 'ICU diaries written by nurses and families help patients by:', '["Increasing the ICU length of stay", "Recording drug doses for legal purposes", "Replacing the official medical record", "Filling memory gaps and reducing PTSD"]'::jsonb, 3, 'They are given to patients after discharge.', 'Ethics, Law & Management'),
(81, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'A positive Babinski sign in an adult (great toe dorsiflexes, toes fan out) indicates:', '["A lower motor neurone lesion in the leg", "A normal plantar reflex in an adult", "An upper motor neurone (corticospinal) lesion", "Peripheral neuropathy from diabetes"]'::jsonb, 2, 'It is normal in infants under about 1 year.', 'Neurology'),
(82, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'Babinski sign is tested by:', '["Flexing the neck forward towards the chest", "Stroking the lateral sole from heel to toes", "Tapping the patellar tendon with a hammer", "Pricking the big toe with a sterile pin"]'::jsonb, 1, 'Normal adult response is plantar flexion of the toes.', 'Neurology'),
(83, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'A patient with GBS has absent knee and ankle jerks. This indicates:', '["Upper motor neurone involvement in the cord", "Spinal shock from an injury above T6", "Lower motor neurone involvement (areflexia)", "A normal finding in critically ill adults"]'::jsonb, 2, 'GBS is a peripheral polyneuropathy; reflexes are lost early.', 'Neurology'),
(84, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'In a trauma patient needing intubation, the airway is secured with:', '["Awake nasal intubation in every trauma case", "RSI with manual in-line stabilisation", "Blind finger sweep and bag ventilation only", "Head tilt and chin lift without neck support"]'::jsonb, 1, 'The front of the collar is removed while an assistant holds the head.', 'Neurology'),
(85, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'Nasal intubation is avoided in trauma with:', '["Suspected basal skull fracture", "Isolated limb fractures", "Mandibular fracture only", "Simple scalp lacerations"]'::jsonb, 0, 'The tube may enter the cranial cavity.', 'Neurology'),
(86, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'A ventilated patient suddenly has high pressure alarms, low tidal volume and cannot pass a suction catheter. The nurse should first:', '["Give a sedative bolus and wait for 10 minutes", "Check the ventilator settings and do nothing else", "Suspect a blocked tube, remove it and bag-mask ventilate", "Increase the PEEP to open up the small airways"]'::jsonb, 2, 'A blocked tube is an emergency; bag-mask ventilation and reintubation follow.', 'Neurology'),
(87, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'The DOPE mnemonic for a ventilated patient deteriorating stands for:', '["Displacement, Obstruction, Pneumothorax, Equipment", "Delirium, Over-sedation, Pain, Exhaustion", "Drugs, Oxygen, Pulse and Electrolytes", "Dehydration, Oedema, Pain and Embolism"]'::jsonb, 0, 'Disconnect from the ventilator and bag with 100% oxygen to troubleshoot.', 'Neurology'),
(88, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'Prevention of endotracheal tube blockage includes:', '["Dry inspired gases to reduce secretions", "Suctioning every 15 minutes as routine", "Instilling large saline volumes routinely", "Humidified gases and suction when needed"]'::jsonb, 3, 'Heated humidifiers or HME filters keep secretions moist.', 'Neurology'),
(89, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'Accidental extubation is most likely when:', '["Tube ties that are checked every shift", "An agitated patient with a poorly secured tube", "A calm, orientated and cooperative patient", "A deeply sedated patient on a ventilator"]'::jsonb, 1, 'Secure fixation, sedation assessment and safe restraint policies reduce risk.', 'Neurology'),
(90, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'The layer of skin containing blood vessels, nerves and sweat glands is the:', '["Epidermis", "Stratum corneum", "Dermis", "Hypodermis only"]'::jsonb, 2, 'The epidermis is avascular.', 'Neurology'),
(91, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'Skin plays a role in thermoregulation mainly through:', '["Sweating and changes in skin blood flow", "Absorbing oxygen from the air", "Producing red cells in the skin", "Producing insulin in the dermis"]'::jsonb, 0, 'Burns and TEN impair this, causing hypothermia.', 'Neurology'),
(92, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'In critically ill patients, skin failure (''acute skin failure'') is caused by:', '["Skin hypoperfusion during multi-organ failure", "Early mobilisation and turning in bed", "Regular use of moisturisers on the skin", "Excessive bathing with soap and water only"]'::jsonb, 0, 'It may cause pressure injuries despite good care.', 'Neurology'),
(93, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'Peripheral polyneuritis causing glove-and-stocking sensory loss is commonly due to:', '["Hypothyroidism on its own", "Excess intake of vitamin C", "Diabetes and vitamin B deficiency", "Hypertension and bronchial asthma"]'::jsonb, 2, 'Alcohol and drugs (e.g. isoniazid without pyridoxine) are other causes.', 'Neurology'),
(94, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'Isoniazid neuropathy is prevented by giving:', '["Pyridoxine (vitamin B6)", "Vitamin K (phytomenadione)", "Folic acid (vitamin B9)", "Ascorbic acid (vitamin C)"]'::jsonb, 0, 'This is important in TB patients in Nigeria.', 'Neurology'),
(95, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'A deep tendon reflex graded 4+ means:', '["Normal, as expected", "Very brisk, with clonus", "Sluggish and diminished", "Absent, even with reinforcement"]'::jsonb, 1, 'Grades: 0 absent, 1+ diminished, 2+ normal, 3+ brisk, 4+ clonus.', 'Neurology'),
(96, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'Spinal shock after cord injury is characterised by:', '["Normal reflexes with weakness", "Hypertension and tachycardia", "Spastic paralysis with hyperreflexia at once", "Flaccid paralysis and areflexia below the injury"]'::jsonb, 3, 'Reflexes return as spinal shock resolves (days to weeks).', 'Neurology'),
(97, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'Neurogenic shock after high cord injury presents with:', '["Hypertension with bradycardia", "Hypotension with tachycardia and cold skin", "Hypotension with bradycardia and warm skin", "Normal blood pressure"]'::jsonb, 2, 'Loss of sympathetic tone causes vasodilation; atropine and vasopressors may be needed.', 'Neurology'),
(98, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'Autonomic dysreflexia in a T4 cord injury patient is triggered by:', '["A low blood sugar level", "A full bladder or constipation", "Excess oral fluid intake", "Hypothermia after bathing"]'::jsonb, 1, 'Sit the patient up and remove the trigger.', 'Neurology'),
(99, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'Decerebrate posturing (extension of arms and legs) indicates:', '["A cortical lesion only", "An isolated spinal cord injury", "Brain stem damage (midbrain/pons)", "A normal response to pain"]'::jsonb, 2, 'It scores M2 on the GCS.', 'Neurology'),
(100, 'Neuro, Airway and Skin: Babinski, Trauma Intubation, Blocked Tube, Polyneuritis', 'Brudzinski''s sign is positive when:', '["The pupils dilate on neck movement", "Neck flexion causes hip and knee flexion", "The knee cannot be fully extended", "The great toe extends upwards on stroking"]'::jsonb, 1, 'It indicates meningeal irritation; Kernig''s sign is pain on knee extension.', 'Neurology'),
(101, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'A 2-year-old with intussusception becomes lethargic and the abdomen is rigid. The nurse should prepare for:', '["Air enema reduction under imaging", "Discharge home with oral antibiotics", "Urgent laparotomy, not enema reduction", "Oral rehydration solution only"]'::jsonb, 2, 'Peritonitis suggests perforation or gangrene.', 'Paediatric'),
(102, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'A classic triad of intussusception is:', '["Bilious vomiting, jaundice and pale, chalky stools", "Projectile vomiting, an olive mass and a metabolic alkalosis", "Colicky pain, sausage-shaped mass, redcurrant jelly stool", "Fever, rash, conjunctivitis and peeling of the fingertips"]'::jsonb, 2, 'Not all three are present in every child.', 'Paediatric'),
(103, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'Appendicitis in a child under 5 is more dangerous because:', '["Early perforation; the omentum is poorly developed", "Young children always present very early", "The pain is always well localised in them", "Appendicitis never occurs below this age"]'::jsonb, 0, 'Generalised peritonitis is common at presentation.', 'Paediatric'),
(104, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'Hirschsprung''s disease is treated definitively by:', '["Long-term laxatives and a high-fibre diet", "Appendicectomy and a temporary ileostomy", "A pull-through operation removing the aganglionic bowel", "Rectal irrigation for life, without surgery"]'::jsonb, 2, 'A colostomy may be needed first.', 'Paediatric'),
(105, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'Malrotation with midgut volvulus is a surgical emergency because:', '["It causes only mild constipation in the infant", "It affects only the stomach and duodenum", "The twisted mesenteric artery causes gut ischaemia", "It resolves without treatment in most babies"]'::jsonb, 2, 'The Ladd''s procedure untwists and fixes the bowel.', 'Paediatric'),
(106, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'Epiglottitis has become less common because of vaccination against:', '["Tuberculosis (BCG)", "Measles (rubeola virus)", "Rotavirus infection", "Haemophilus influenzae type b"]'::jsonb, 3, 'Hib vaccine is part of the pentavalent vaccine.', 'Paediatric'),
(107, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'A child with suspected epiglottitis should:', '["Lie flat on a trolley for a lateral neck X-ray", "Be kept calm with a parent, with airway expert present", "Have an IV cannula inserted immediately", "Have the throat examined with a spatula at once"]'::jsonb, 1, 'Upsetting the child may cause complete obstruction.', 'Paediatric'),
(108, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'Sudden infant death syndrome is most common at age:', '["1–2 years", "5–6 years", "Newborn first week", "2–4 months"]'::jsonb, 3, 'Risk factors: prone sleeping, smoking, overheating, soft bedding.', 'Paediatric'),
(109, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'A baby is brought in apnoeic and pulseless at home. The nurse should:', '["Give oxygen by mask and observe", "Wait for the doctor to confirm death", "Ask the parents what happened first", "Start paediatric CPR and call the team"]'::jsonb, 3, 'Infants receive 15:2 compressions to breaths with two rescuers.', 'Paediatric'),
(110, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'Acute lymphoblastic leukaemia treatment in ICU may cause:', '["Neutropenic sepsis and tumour lysis syndrome", "Immediate iron overload needing chelation", "Hypercoagulability with deep vein thrombosis", "Polycythaemia with hyperviscosity and stroke"]'::jsonb, 0, 'Prophylactic allopurinol or rasburicase and hydration prevent TLS.', 'Paediatric'),
(111, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'Platelet transfusion in a leukaemic child is usually given when the count falls below:', '["150 × 10⁹/L in every child", "10 × 10⁹/L, or higher if bleeding", "100 × 10⁹/L, even if not bleeding", "400 × 10⁹/L before any procedure"]'::jsonb, 1, 'Higher thresholds are used before procedures.', 'Paediatric'),
(112, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'In Ebola, health workers must remove PPE:', '["In the patient''s room with the patient watching", "Without hand hygiene", "Quickly in any order", "In a set sequence with a trained observer"]'::jsonb, 3, 'Most health worker infections occur during PPE removal.', 'Paediatric'),
(113, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'The incubation period of Ebola virus disease is:', '["1–2 hours", "2 months", "1 year", "2–21 days"]'::jsonb, 3, 'Contacts are followed up for 21 days.', 'Paediatric'),
(114, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'A child with Ebola is not infectious:', '["Before symptoms begin", "After death", "During the vomiting phase", "When bleeding"]'::jsonb, 0, 'Bodies remain highly infectious.', 'Paediatric'),
(115, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'Severe pneumonia in a child is suggested by:', '["A normal breathing rate for the child''s age", "Chest indrawing, grunting or SpO₂ below 90%", "A mild dry cough lasting for a few days", "A runny nose with sneezing and mild fever"]'::jsonb, 1, 'WHO danger signs also include inability to drink and convulsions.', 'Paediatric'),
(116, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'The respiratory rate considered fast breathing in a child aged 2–12 months is:', '["20 breaths/min or more", "80 breaths/min or more", "50 breaths/min or more", "30 breaths/min or more"]'::jsonb, 2, 'For 1–5 years: 40 or more; under 2 months: 60 or more.', 'Paediatric'),
(117, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'A child with diabetic ketoacidosis should have fluids replaced:', '["Only by mouth, with no IV fluids", "Slowly over 48 hours to reduce cerebral oedema", "Rapidly over 2 hours to correct shock", "With hypotonic fluid to lower sodium"]'::jsonb, 1, 'Boluses are limited to those in shock.', 'Paediatric'),
(118, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'Neonatal tetanus is prevented by:', '["Maternal tetanus toxoid and clean cord care", "Vitamin K injection given at birth", "Antibiotics given to every baby at birth", "Routine BCG given in the first week"]'::jsonb, 0, 'It presents with inability to suck and spasms around day 7.', 'Paediatric'),
(119, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'Kwashiorkor in a critically ill child presents with:', '["Oedema, skin changes and low albumin", "High albumin with polycythaemia", "Obesity with hypertension", "Severe wasting without any oedema"]'::jsonb, 0, 'Refeeding must be slow; correct hypoglycaemia and hypothermia first.', 'Paediatric'),
(120, 'Paediatric Surgical, Respiratory and Haematological Emergencies', 'Severe acute malnutrition with shock is treated with:', '["No IV or oral fluids at all until feeding", "Cautious IV fluids (15 mL/kg) with close monitoring", "IV diuretics to remove excess body water", "Rapid 60 mL/kg boluses over 15 minutes"]'::jsonb, 1, 'These children easily develop heart failure.', 'Paediatric'),
(121, 'Obstetric Critical Care: Thin Topics', 'A woman at 34 weeks lies flat for a scan and becomes pale, sweaty and hypotensive. The nurse should:', '["Turn her to the left lateral position", "Raise both legs and keep her flat", "Give IV furosemide", "Sit her upright at 90 degrees"]'::jsonb, 0, 'Supine hypotensive syndrome is relieved by relieving IVC compression.', 'Obstetric & Neonatal'),
(122, 'Obstetric Critical Care: Thin Topics', 'Cervical cerclage is usually inserted at:', '["12–14 weeks of gestation", "4–6 weeks of gestation", "28–30 weeks of gestation", "36–38 weeks of gestation"]'::jsonb, 0, 'It is removed at about 37 weeks or if labour starts.', 'Obstetric & Neonatal'),
(123, 'Obstetric Critical Care: Thin Topics', 'Puerperal sepsis can progress rapidly to septic shock. An early sign is:', '["An increased appetite and good sleep", "Bradycardia with hypertension and headache", "A normal temperature with a calm patient", "Tachycardia and tachypnoea with abdominal tenderness"]'::jsonb, 3, 'Fever may be absent in severe sepsis; MEOWS triggers escalation.', 'Obstetric & Neonatal'),
(124, 'Obstetric Critical Care: Thin Topics', 'The ''3 delays'' model for maternal death refers to delays in:', '["Deciding to seek care, reaching care, receiving care", "Diagnosis, treatment and payment of bills", "Labour, delivery and discharge from hospital", "Booking, scanning and laboratory testing"]'::jsonb, 0, 'Addressing these reduces maternal mortality in Nigeria.', 'Obstetric & Neonatal'),
(125, 'Obstetric Critical Care: Thin Topics', 'Obstetric haemorrhage of 1500 mL with ongoing bleeding needs:', '["Activation of the massive haemorrhage protocol", "Oral iron tablets and review next day", "IV diuretics to reduce fluid overload", "Observation of vital signs for 4 hours"]'::jsonb, 0, 'Give blood products, tranexamic acid and treat the cause.', 'Obstetric & Neonatal'),
(126, 'Obstetric Critical Care: Thin Topics', 'In placenta accreta spectrum, the placenta:', '["Separates completely before the baby is born", "Lies over the cervix and bleeds painlessly", "Is much smaller than normal for gestation", "Invades the uterine wall and fails to separate"]'::jsonb, 3, 'Previous caesarean section is the major risk factor; hysterectomy may be needed.', 'Obstetric & Neonatal'),
(127, 'Obstetric Critical Care: Thin Topics', 'Peripartum cardiomyopathy presents with:', '["Sudden tearing chest pain radiating to the back", "Hypertension and seizures without heart failure", "Heart failure in late pregnancy or months after", "Fever with a widespread rash and joint pains"]'::jsonb, 2, 'It is relatively common in northern Nigeria.', 'Obstetric & Neonatal'),
(128, 'Obstetric Critical Care: Thin Topics', 'Oxytocin infusion is given cautiously in patients with heart disease because it can cause:', '["Hypotension, tachycardia and fluid overload", "Severe hyperkalaemia", "Hypertension with a slow heart rate", "Profound hypoglycaemia"]'::jsonb, 0, 'Large volumes of dilute oxytocin can cause water intoxication.', 'Obstetric & Neonatal'),
(129, 'Obstetric Critical Care: Thin Topics', 'Ergometrine is contraindicated in:', '["Pre-eclampsia and heart disease", "Mild iron-deficiency anaemia", "Primary postpartum haemorrhage", "Uterine atony after delivery"]'::jsonb, 0, 'It causes severe hypertension and coronary spasm.', 'Obstetric & Neonatal'),
(130, 'Obstetric Critical Care: Thin Topics', 'Carboprost (15-methyl PGF2α) should be avoided in:', '["Diabetes", "Anaemia", "Hypertension", "Asthma"]'::jsonb, 3, 'It causes bronchospasm.', 'Obstetric & Neonatal'),
(131, 'Obstetric Critical Care: Thin Topics', 'Sickle cell disease in pregnancy increases the risk of:', '["Crises, pre-eclampsia, infection and growth restriction", "Post-term pregnancy continuing beyond 42 weeks", "Polycythaemia and hyperviscosity in the mother", "Fetal macrosomia and shoulder dystocia at delivery"]'::jsonb, 0, 'Folic acid, malaria prophylaxis and close monitoring are needed.', 'Obstetric & Neonatal'),
(132, 'Obstetric Critical Care: Thin Topics', 'Severe malaria in pregnancy is treated with:', '["Oral metronidazole", "IV artesunate", "IM penicillin", "Oral chloroquine only"]'::jsonb, 1, 'Pregnant women are at high risk of hypoglycaemia and pulmonary oedema.', 'Obstetric & Neonatal'),
(133, 'Obstetric Critical Care: Thin Topics', 'Polyhydramnios with a fetus that cannot swallow suggests:', '["Post-maturity beyond 42 weeks", "Bilateral fetal renal agenesis", "Placental insufficiency and IUGR", "Oesophageal atresia or neurological anomaly"]'::jsonb, 3, 'A nasogastric tube is passed at birth to check oesophageal patency.', 'Obstetric & Neonatal'),
(134, 'Obstetric Critical Care: Thin Topics', 'A growth-restricted baby at delivery requires preparation for:', '["Fluid overload and generalised oedema", "Hyperglycaemia and polyuria at birth", "Resuscitation, hypoglycaemia and hypothermia", "Macrosomia and shoulder dystocia"]'::jsonb, 2, 'Early feeding and warmth are essential.', 'Obstetric & Neonatal'),
(135, 'Obstetric Critical Care: Thin Topics', 'Women with a history of second-trimester loss from cervical weakness may be offered:', '["Routine caesarean section at 20 weeks", "Strict bed rest only for the whole pregnancy", "No treatment, as recurrence is very rare", "Cervical length scans with cerclage or progesterone"]'::jsonb, 3, 'A short cervix on scan is an indication.', 'Obstetric & Neonatal'),
(136, 'Obstetric Critical Care: Thin Topics', 'Pulmonary oedema in severe pre-eclampsia is worsened by:', '["Magnesium sulphate", "Fluid restriction", "Excessive IV fluids", "Left lateral position"]'::jsonb, 2, 'Fluids are restricted to about 80 mL/hour.', 'Obstetric & Neonatal'),
(137, 'Obstetric Critical Care: Thin Topics', 'After delivery, a woman on magnesium sulphate has respiratory rate 8/min. The nurse should:', '["Increase the magnesium dose to prevent fits", "Encourage breastfeeding to help recovery", "Stop the infusion and give IV calcium gluconate", "Give a sedative to calm the patient"]'::jsonb, 2, 'Respiratory depression is a sign of toxicity.', 'Obstetric & Neonatal'),
(138, 'Obstetric Critical Care: Thin Topics', 'Retained products of conception after delivery cause:', '["Secondary PPH and infection", "Hyperemesis gravidarum", "Hypertension and seizures", "Polyhydramnios in the next pregnancy"]'::jsonb, 0, 'Evacuation under antibiotic cover is needed.', 'Obstetric & Neonatal'),
(139, 'Obstetric Critical Care: Thin Topics', 'The nurse should monitor a woman after caesarean section with general anaesthesia for:', '["Hypoglycaemia only, every hour", "Airway, bleeding, uterine tone and pain", "Visual acuity only, every hour", "Polyuria only, every hour"]'::jsonb, 1, 'Observations are recorded on the MEOWS chart.', 'Obstetric & Neonatal'),
(140, 'Obstetric Critical Care: Thin Topics', 'Maternal hypothermia after massive transfusion worsens:', '["The blood pressure only", "Uterine contraction", "Coagulopathy and bleeding", "The urine output only"]'::jsonb, 2, 'All fluids and blood are warmed.', 'Obstetric & Neonatal'),
(141, 'Ethico-legal Issues: Thin Topics', 'The Code of Professional Conduct for nurses mainly sets out:', '["Standards of behaviour and duties nurses must follow", "The prescribing rules that apply to doctors", "The salaries that nurses should receive each grade", "The building requirements for hospitals and clinics"]'::jsonb, 0, 'Breaches may lead to NMCN disciplinary action.', 'Ethics, Law & Management'),
(142, 'Ethico-legal Issues: Thin Topics', 'A Do-Not-Resuscitate decision should be:', '["Clearly documented, discussed and reviewed", "Made by the bedside nurse alone at night", "Applied automatically to all elderly patients", "Kept secret from the rest of the team"]'::jsonb, 0, 'It applies only to CPR, not other treatments.', 'Ethics, Law & Management'),
(143, 'Ethico-legal Issues: Thin Topics', 'Passive euthanasia is sometimes confused with:', '["Starting CPR in an unexpected cardiac arrest", "Giving adequate pain relief at the end of life", "Feeding the patient by nasogastric tube", "Withdrawing or withholding futile treatment"]'::jsonb, 3, 'Withdrawing futile treatment is lawful when properly decided; actively killing is not.', 'Ethics, Law & Management'),
(144, 'Ethico-legal Issues: Thin Topics', 'A dying declaration recorded by a nurse is valuable in court because:', '["It replaces the need for a police investigation", "It is always written down by a lawyer", "A person facing death is presumed to be truthful", "It counts as a formal medical diagnosis"]'::jsonb, 2, 'Accuracy, time and witnesses must be recorded.', 'Ethics, Law & Management'),
(145, 'Ethico-legal Issues: Thin Topics', 'A swab left inside a patient after surgery would allow the doctrine of:', '["Double effect", "Vicarious immunity", "Good Samaritan", "Res ipsa loquitur"]'::jsonb, 3, 'The thing speaks for itself; negligence is inferred.', 'Ethics, Law & Management'),
(146, 'Ethico-legal Issues: Thin Topics', 'The Patient''s Bill of Rights includes the right to:', '["Choose any staff member''s salary", "Read the notes of other patients", "Know who is providing their care", "Refuse to pay all hospital bills"]'::jsonb, 2, 'Patients also have responsibilities, such as giving accurate information.', 'Ethics, Law & Management'),
(147, 'Ethico-legal Issues: Thin Topics', 'A patient bitten by a dog should have the wound:', '["Covered with a dressing without cleaning", "Left untreated if the wound is small", "Washed with soap and water for 15 minutes", "Sutured tightly at once to stop bleeding"]'::jsonb, 2, 'Rabies vaccine and immunoglobulin follow as indicated.', 'Ethics, Law & Management'),
(148, 'Ethico-legal Issues: Thin Topics', 'Good Samaritan laws do not apply when the nurse:', '["Gives first aid at a church", "Is on duty and has a duty of care", "Helps at a road crash off duty", "Assists at a market collapse"]'::jsonb, 1, 'On duty, normal professional standards apply.', 'Ethics, Law & Management'),
(149, 'Ethico-legal Issues: Thin Topics', 'The legal term for a person who brings a negligence claim is:', '["Defendant", "Witness", "Judge", "Plaintiff"]'::jsonb, 3, 'The defendant is the person or institution sued.', 'Ethics, Law & Management'),
(150, 'Ethico-legal Issues: Thin Topics', 'Malpractice differs from negligence in that malpractice:', '["It is negligence by a professional in their role", "It is always intentional and criminal", "It applies only to doctors, not nurses", "It has no legal consequence at all"]'::jsonb, 0, 'Elements: duty, breach, causation and damage.', 'Ethics, Law & Management'),
(151, 'Ethico-legal Issues: Thin Topics', 'An ICU nurse who leaves her shift without handover may be liable for:', '["Abandonment of patients", "Res ipsa loquitur", "Good professional practice", "Vicarious immunity"]'::jsonb, 0, 'Patient care must be handed over before leaving.', 'Ethics, Law & Management'),
(152, 'Ethico-legal Issues: Thin Topics', 'Assault means:', '["A threat of unlawful touching", "Actual unlawful touching", "Lawful physical restraint", "Valid consent to treatment"]'::jsonb, 0, 'Battery is the actual touching without consent.', 'Ethics, Law & Management'),
(153, 'Ethico-legal Issues: Thin Topics', 'When a patient wants to leave ICU against medical advice, the nurse should:', '["Lock the doors so that the patient cannot leave", "Sedate the patient to keep them in the unit", "Ignore the request and continue the care", "Explain the risks, inform the doctor, document"]'::jsonb, 3, 'A competent patient can refuse treatment.', 'Ethics, Law & Management'),
(154, 'Ethico-legal Issues: Thin Topics', 'A nurse who discloses a patient''s HIV status to the patient''s employer without consent has committed:', '["An act of beneficence", "Good professional practice", "An example of fidelity", "Breach of confidentiality"]'::jsonb, 3, 'Disclosure requires consent or legal requirement.', 'Ethics, Law & Management'),
(155, 'Ethico-legal Issues: Thin Topics', 'Ethical dilemmas in ICU are best resolved by:', '["Ignoring the problem until it goes away", "Following whoever argues the loudest", "The most junior nurse deciding on behalf of all", "Team discussion using ethics and the patient''s values"]'::jsonb, 3, 'Ethics committees may help.', 'Ethics, Law & Management'),
(156, 'Ethico-legal Issues: Thin Topics', 'Felony-related cases in ICU (e.g. gunshot wounds) require the nurse to:', '["Refuse to treat the patient until police arrive", "Discharge the patient quickly to avoid trouble", "Give care and notify police as the law requires", "Investigate the crime personally at the bedside"]'::jsonb, 2, 'Treatment comes first; evidence is handled properly.', 'Ethics, Law & Management'),
(157, 'Ethico-legal Issues: Thin Topics', 'Telephone orders in an emergency should be:', '["Read back, documented and countersigned", "Ignored until a doctor attends in person", "Accepted from any caller on the phone", "Accepted without writing anything down"]'::jsonb, 0, 'Read-back reduces errors.', 'Ethics, Law & Management'),
(158, 'Ethico-legal Issues: Thin Topics', 'Professional accountability means the nurse:', '["She avoids making any decisions", "She is never responsible for any outcome", "She shifts all blame to the doctors", "She answers for her actions and omissions"]'::jsonb, 3, 'Accountability is to the patient, employer, NMCN and law.', 'Ethics, Law & Management'),
(159, 'Ethico-legal Issues: Thin Topics', 'Standards of practice are used in court to judge whether:', '["The patient had paid all the hospital bills", "She was the best nurse in the whole hospital", "She acted as a reasonably competent nurse would", "A doctor was present when she gave care"]'::jsonb, 2, 'This is the ''reasonable nurse'' standard.', 'Ethics, Law & Management'),
(160, 'Ethico-legal Issues: Thin Topics', 'A nurse ordered by a doctor to give a clearly wrong dose should:', '["Give it because the doctor wrote the order", "Question the order and withhold until clarified", "Give half the dose as a compromise", "Ask the patient to decide what to do"]'::jsonb, 1, 'The nurse is accountable for drugs she gives.', 'Ethics, Law & Management'),
(161, 'ICU Management III', 'ICU organisation in the curriculum includes the role of the nurse in:', '["Hospital finance, billing and insurance claims only", "Surgery and anaesthesia in the main theatre only", "Unit organisation, staffing, equipment and quality", "Pharmacy dispensing and stock control only"]'::jsonb, 2, 'The ICU nurse manager coordinates people, resources and standards.', 'Ethics, Law & Management'),
(162, 'ICU Management III', 'The most appropriate ICU nurse-patient ratio for a Level 2 (HDU) patient is:', '["1:4", "1:8", "1:2", "1:1"]'::jsonb, 2, 'Level 3 patients need 1:1.', 'Ethics, Law & Management'),
(163, 'ICU Management III', 'An ICU duty roster should be planned:', '["In advance, balancing skill mix, leave, continuity", "Without considering skill mix, using staff names only", "Daily at the start of each shift by whoever is in charge", "By the patients'' relatives at the weekly family meeting"]'::jsonb, 0, 'Fair rosters reduce absenteeism.', 'Ethics, Law & Management'),
(164, 'ICU Management III', 'Span of control in ICU management refers to:', '["Staff one leader can supervise effectively", "The number of ventilators in the unit", "The total budget of the ICU each year", "The size of the ICU in number of beds"]'::jsonb, 0, 'A narrow span allows closer supervision.', 'Ethics, Law & Management'),
(165, 'ICU Management III', 'Decision-making in ICU management follows the steps:', '["Decide first, and then look for the problem", "Ask only the patient''s relatives to decide", "Identify, gather data, weigh options, decide, evaluate", "Choose an option at random and hope"]'::jsonb, 2, 'Evaluation completes the cycle.', 'Ethics, Law & Management'),
(166, 'ICU Management III', 'Delegation of a task to a junior nurse requires:', '["Complete transfer of all accountability", "Right task, person, communication and supervision", "No explanation to the person delegated", "Only the absence of the senior nurse"]'::jsonb, 1, 'The delegator remains accountable.', 'Ethics, Law & Management'),
(167, 'ICU Management III', 'Staff motivation in ICU is improved by:', '["Recognition, training and involvement", "Constant criticism of mistakes", "Withholding unit information", "Unequal and unfair workloads"]'::jsonb, 0, 'Motivated staff give better care.', 'Ethics, Law & Management'),
(168, 'ICU Management III', 'Disciplinary action in an ICU should be:', '["Immediate and in front of colleagues", "Fair, documented and following due process", "Without hearing the staff member", "Based on rumours from other staff"]'::jsonb, 1, 'Progressive discipline starts with counselling.', 'Ethics, Law & Management'),
(169, 'ICU Management III', 'Accounting and budgeting in ICU management help to:', '["Increase waste of disposable items in the unit", "Avoid planning so that money can be used freely", "Hide the true costs from the hospital management", "Plan and control spending on staff, drugs and equipment"]'::jsonb, 3, 'Variance analysis compares actual and planned spending.', 'Ethics, Law & Management'),
(170, 'ICU Management III', 'Job performance evaluation should be based on:', '["Rumours and complaints from patients", "The manager''s personal likes and dislikes", "The age and seniority of the staff", "Clear standards and objective evidence"]'::jsonb, 3, 'Feedback is given regularly, not only annually.', 'Ethics, Law & Management'),
(171, 'ICU Management III', 'An ICU equipment inventory is used to:', '["Track equipment, maintenance and replacement", "Document drug errors and near misses", "Plan annual leave for the nursing staff", "Record patient diagnoses and outcomes"]'::jsonb, 0, 'Each item has a service history.', 'Ethics, Law & Management'),
(172, 'ICU Management III', 'Interdepartmental communication between ICU and laboratory improves:', '["The length of the family visiting hours", "The spread of rumours among the staff", "Speed and accuracy of critical results", "The quality of catering for the patients"]'::jsonb, 2, 'Critical results are phoned and documented with read-back.', 'Ethics, Law & Management'),
(173, 'ICU Management III', 'The role of an ICU link nurse for infection control is to:', '["Perform surgical drainage of infections", "Promote infection prevention and audit compliance", "Replace the hospital infection control team", "Prescribe antibiotics for infected patients"]'::jsonb, 1, 'Link nurses connect the unit with the infection control team.', 'Ethics, Law & Management'),
(174, 'ICU Management III', 'Clinical governance in ICU includes:', '["Audit, risk management, training, patient involvement", "Only the recruitment of new staff", "Only the financial management of the unit", "Only the maintenance of the buildings"]'::jsonb, 0, 'It ensures accountability for quality.', 'Ethics, Law & Management'),
(175, 'ICU Management III', 'An ICU admission request for a patient with no chance of recovery should prompt:', '["Refusal without any explanation to the team", "Transfer to another hospital without notice", "Senior discussion of goals of care and options", "Immediate admission without any discussion"]'::jsonb, 2, 'Palliative care may be more appropriate.', 'Ethics, Law & Management'),
(176, 'ICU Management III', 'Readmission to ICU within 48 hours of discharge is a marker of:', '["Good ward staffing and early review", "Possible premature discharge or poor ward care", "Low patient acuity across the hospital", "Excellent ICU care and good outcomes"]'::jsonb, 1, 'It is a quality indicator.', 'Ethics, Law & Management'),
(177, 'ICU Management III', 'Nursing workload in ICU can be measured with tools such as:', '["The Braden pressure ulcer scale", "TISS or NAS (Nursing Activities Score)", "The Bishop score for labour", "The APGAR score at birth"]'::jsonb, 1, 'These help plan staffing.', 'Ethics, Law & Management'),
(178, 'ICU Management III', 'The best approach to new technology introduction in ICU is:', '["Training, protocols and evaluation before full use", "Letting one nurse decide how it is used", "Keeping it locked away until it is needed", "Immediate use without any staff training"]'::jsonb, 0, 'Competency must be assessed.', 'Ethics, Law & Management'),
(179, 'ICU Management III', 'A sentinel event in ICU is:', '["A normal shift change with handover", "A routine planned admission from theatre", "A planned discharge to the ward in the day", "An unexpected event causing death or serious harm"]'::jsonb, 3, 'It requires root cause analysis.', 'Ethics, Law & Management'),
(180, 'ICU Management III', 'Visiting policies in ICU should balance:', '["Family needs, patient rest and infection control", "Unlimited visitors at all hours of the day", "Staff convenience and nothing else", "Strict exclusion of all visitors at all times"]'::jsonb, 0, 'Flexible visiting is associated with family satisfaction.', 'Ethics, Law & Management'),
(181, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Martha Rogers'' Science of Unitary Human Beings views the person as:', '["A set of separate, independent organ systems", "A passive recipient of nursing care", "An energy field interacting with the environment", "A machine that needs to be repaired"]'::jsonb, 2, 'Key concepts: energy fields, openness, pattern and pandimensionality.', 'Research & Nursing Process'),
(182, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Gordon''s functional health patterns are used mainly for:', '["Organising assessment into 11 patterns", "Planning the ICU''s annual budget", "Classifying surgical wounds", "Calculating drug doses in children"]'::jsonb, 0, 'Examples: nutrition-metabolic, elimination, activity-exercise, cognitive-perceptual.', 'Research & Nursing Process'),
(183, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Betty Neuman''s systems model focuses on:', '["Self-care deficits and nursing systems", "Environmental cleanliness and fresh air only", "Responses to stressors and lines of defence", "Interpersonal phases of the relationship"]'::jsonb, 2, 'Prevention is primary, secondary or tertiary.', 'Research & Nursing Process'),
(184, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Quality assurance in ICU uses Donabedian''s framework of:', '["Planning, organising and controlling", "Input, output and feedback only", "Assessment, diagnosis and planning", "Structure, process and outcome"]'::jsonb, 3, 'Structure: resources; process: activities; outcome: results.', 'Research & Nursing Process'),
(185, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Critical thinking in the ICU nurse is shown by:', '["Following routine without any question", "Noticing subtle changes, questioning and acting", "Recording observations without analysis", "Waiting for doctors to notice any change"]'::jsonb, 1, 'It underpins clinical judgement.', 'Research & Nursing Process'),
(186, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Reflective practice using Gibbs'' cycle includes:', '["Assess, diagnose, plan, implement and evaluate care", "Description, feelings, evaluation, analysis, conclusion, action", "Input, process, output and feedback as a system", "Plan, do, study and act, repeated as a quality cycle"]'::jsonb, 1, 'It helps nurses learn from experience.', 'Research & Nursing Process'),
(187, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'A health talk to a group of ICU relatives should start with:', '["Assessing their learning needs", "A long lecture using jargon", "Handing out leaflets only", "Testing their knowledge first"]'::jsonb, 0, 'Teaching is planned around needs.', 'Research & Nursing Process'),
(188, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'The ''politics of health care'' affects ICU nursing through:', '["Nurses'' personal voting choices", "Individual patient diagnoses", "Funding, staffing decisions and policy", "The pharmacology of ICU drugs"]'::jsonb, 2, 'Nurse leaders advocate for resources.', 'Research & Nursing Process'),
(189, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Subjective Global Assessment grade C means the patient is:', '["Severely malnourished", "Obese", "Well nourished", "Mildly malnourished"]'::jsonb, 0, 'SGA uses history and physical examination.', 'Research & Nursing Process'),
(190, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Nutrition in acute kidney injury without dialysis aims for:', '["Enough calories, moderate protein, electrolyte control", "Fasting until the kidney function improves", "No protein at all until the kidneys recover", "Unlimited potassium in the feeds"]'::jsonb, 0, 'Protein needs rise if dialysis starts.', 'Research & Nursing Process'),
(191, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Feeding a diabetic ICU patient enterally requires:', '["Adding sugar to the feeds to prevent lows", "No glucose checks while on enteral feeds", "Glucose checks and insulin matched to the feed", "Stopping all feeds to control the glucose"]'::jsonb, 2, 'Interrupting feeds without adjusting insulin causes hypoglycaemia.', 'Research & Nursing Process'),
(192, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Respiratory muscle training is mainly indicated in:', '["An active, undrained pneumothorax", "Unconscious patients only", "Weak inspiratory muscles and difficult weaning", "Patients with normal lungs and strength"]'::jsonb, 2, 'Training improves diaphragm strength.', 'Research & Nursing Process'),
(193, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Postural drainage uses gravity to:', '["Drain secretions from specific lung segments", "Improve the patient''s appetite and feeding", "Increase the blood pressure in hypotension", "Reduce the intracranial pressure after injury"]'::jsonb, 0, 'Head-down positions are avoided in raised ICP.', 'Research & Nursing Process'),
(194, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'TENS (transcutaneous electrical nerve stimulation) should not be placed:', '["On the lower back over the muscles", "On the legs over the thigh muscles", "On the arms over the forearm muscles", "Over a pacemaker or the front of the neck"]'::jsonb, 3, 'It may interfere with pacemakers and the carotid sinus.', 'Research & Nursing Process'),
(195, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Sterilisation by steam (autoclave) at 134 °C usually takes:', '["24 hours holding time", "3 minutes holding time", "30 seconds holding time", "1 hour holding time"]'::jsonb, 1, '121 °C requires 15 minutes holding time.', 'Research & Nursing Process'),
(196, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Chemical indicators (indicator tape) on packs show that:', '["The pack is new and has not been opened", "The contents are definitely sterile inside", "The pack is free of all bacterial spores", "The pack was exposed to the sterilising process"]'::jsonb, 3, 'Biological indicators confirm killing of spores.', 'Research & Nursing Process'),
(197, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'High-level disinfection kills:', '["Only bacteria, not viruses or fungi", "All spores in every case, like sterilisation", "Only viruses, not bacteria or fungi", "All organisms except large numbers of spores"]'::jsonb, 3, 'It is used for semi-critical items such as laryngoscopes.', 'Research & Nursing Process'),
(198, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'Hospital-acquired infection is defined as an infection appearing:', '["48 hours or more after admission, not incubating", "Only after the patient has been discharged", "Only in surgical patients after an operation", "Within 6 hours of admission to the hospital"]'::jsonb, 0, 'ICU patients are at highest risk.', 'Research & Nursing Process'),
(199, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'The leading hospital-acquired infection in ventilated ICU patients is:', '["Ventilator-associated pneumonia", "Conjunctivitis", "Skin infection", "Urinary tract infection only"]'::jsonb, 0, 'The VAP bundle reduces it.', 'Research & Nursing Process'),
(200, 'Theories, Quality, Teaching, Nutrition, Physiotherapy and Sterilisation', 'A sickle cell disease patient''s haemoglobin genotype is:', '["HbAS", "HbAC", "HbSS", "HbAA"]'::jsonb, 2, 'HbAS is the carrier (trait).', 'Research & Nursing Process');
insert into public.questions (id, topic, source, q, opts, ans_idx, exp, category, category_icon, is_active)
insert into public.exam_exams (title, instructions, starts_at, ends_at, duration_minutes, question_ids,
